 static CalibrationStage Test(int watts,string folder,CalibrationCpu cpu){var stage=new CalibrationStage{Watts=watts};string journal=Path.Combine(folder,"cpu-lease.json");Process child=null;MemoryMappedViewAccessor view=null;ZeroPowerLease lease=null;try{
