 static int Run(int firstWatts=8){Console.CancelKeyPress+=(s,e)=>{e.Cancel=true;cancel=true;};bool first;using(var mutex=new Mutex(true,@"Global\ThinkPadModes.Calibration",out first)){if(!first){Console.WriteLine("Une calibration est déjà active.");return 75;}string folder=Path.Combine(Root,Guid.NewGuid().ToString("N"));var stages=new List<CalibrationStage>();string error=null;try{LenovoOemTransport.Verify();if(firstWatts==15){string previous=Path.Combine(Root,"f2822ca252c542d2b9aec71d63d22a65");string[] hashes={"A2FA66BCD5518CF0CBBBFE407D42052DC2253AD389C7E04E925D1C846E996991","B4A52333DB1306F4A6DB71F0EF6C5C49D96BCB286908737A2A32CF4BF5B9D710"};int index=0;foreach(int w in new[]{8,10}){string file=Path.Combine(previous,"stage-"+w+"w.json");if(Digest.Of(file)!=hashes[index++])throw new IOException("Preuve de reprise8/10W différente");var old=Json.Deserialize<CalibrationStage>(File.ReadAllText(file));if(!old.Completed||!old.ValidZeroDb||old.BurnMs<180000||old.NonzeroFanSamples!=0||old.MissingFanSamples!=0||old.MaxCpu>80||old.MaxGpu>=80)throw new IOException("Ancien palier non qualifié");stages.Add(old);}initialRestartVerified=true;}Protect(Root);Protect(folder);if(!WindowsPower.OnMains())throw new IOException("Brancher le chargeur");var a=CoolingClient.Send("set","Auto");if(!a.Ok)throw new IOException(a.Error);long autoStart=Tick;while(true){var check=CoolingClient.Send("status");if(!check.Ok)throw new IOException(check.Error);if(check.Snapshot.Faulted){string faultPath=Path.Combine(CoolingPaths.Data,"fault.json");var fault=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(faultPath));string newest=Directory.GetDirectories(Path.Combine(CoolingPaths.Data,"runs")).OrderByDescending(x=>Directory.GetLastWriteTimeUtc(x)).First();var sdk=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(newest,"sdk-status.json")));if(CoolingPaths.Info().Version!="native-20261115-ba8da44bb212"||!(bool)fault["AutomaticRestored"]||!sdk.ContainsKey("Error")||C